pub fn validate(root: &Path, requirement: &Requirement) -> Vec<String> {
    let result = (|| -> Result<Vec<String>> {
        let root = root.canonicalize().map_err(|e| e.to_string())?;
        let path = format!("evidence/{}.json", requirement.id);
        let evidence: Evidence = serde_json::from_str(&read(&root, Path::new(&path))?)
            .map_err(|e| format!("{path}: invalid evidence JSON: {e}"))?;
        let mut errors = Vec::new();
        if evidence.requirement != requirement.requirement {
            errors.push("requirement text differs from the book".into());
        }
        if evidence.inputs.is_empty() {
            errors.push("inputs must contain at least one source or test excerpt".into());
        }
        for input in evidence.inputs {
            match snapshot(&root, &input.path, input.line_start, input.line_end) {
                Err(error) => errors.push(error),
                Ok(current) if current.contents != input.contents => errors.push(format!(
                    "{}:{}..{} no longer matches contents",
                    input.path, input.line_start, input.line_end
                )),
                Ok(_) => {}
            }
        }
        Ok(errors)
    })();
    result.unwrap_or_else(|e| vec![e]).into_iter().map(|error| {
        format!("{}: {error}; revalidate this requirement using the revalidate skill (.agents/skills/revalidate/SKILL.md)", requirement.id)
    }).collect()
}

fn read(root: &Path, relative: &Path) -> Result<String> {
    fs::read_to_string(contained(root, relative)?)
        .map_err(|e| format!("{}: {e}", relative.display()))
}

fn contained(root: &Path, relative: &Path) -> Result<PathBuf> {
    if relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|c| !matches!(c, Component::Normal(_) | Component::CurDir))
    {
        return Err(format!(
            "expected a repository-relative path without '..': {}",
            relative.display()
        ));
    }
    let path = root
        .join(relative)
        .canonicalize()
        .map_err(|e| format!("{}: {e}", relative.display()))?;
    if !path.starts_with(root) {
        return Err(format!("path escapes repository: {}", relative.display()));
    }
    Ok(path)
}

fn missing_stale_and_malformed_evidence_request_revalidation() {
    let f = Fixture::new();
    let errors = f.errors();
    assert!(errors[0].contains("test.rule"));
    assert!(errors[0].contains("revalidate this requirement using the revalidate skill"));
    f.write("evidence/test.rule.json", "{");
    assert!(f.errors()[0].contains("invalid evidence JSON"));
    let mut evidence = f.evidence();
    evidence["requirement"] = "Old requirement".into();
    evidence["inputs"][0]["contents"] = "old contents".into();
    f.save(&evidence);
    let errors = f.errors();
    assert_eq!(errors.len(), 2);
    assert!(errors.iter().all(|e| e.contains("revalidate")));
}

fn all_schema_fields_reject_wrong_types_and_missing_inputs() {
    let f = Fixture::new();
    for (key, value) in [
        ("requirement", json!(null)),
        ("inputs", json!({})),
        ("justification", json!(4)),
    ] {
        let mut evidence = f.evidence();
        evidence[key] = value;
        f.save(&evidence);
        assert!(!f.errors().is_empty(), "{key}");
    }
    for key in ["path", "line_start", "line_end", "contents"] {
        let mut evidence = f.evidence();
        evidence["inputs"][0].as_object_mut().unwrap().remove(key);
        f.save(&evidence);
        assert!(!f.errors().is_empty(), "missing {key}");
        let mut evidence = f.evidence();
        evidence["inputs"][0][key] = json!(null);
        f.save(&evidence);
        assert!(!f.errors().is_empty(), "null {key}");
    }
    let mut evidence = f.evidence();
    evidence["inputs"][0]["extra"] = json!(false);
    f.save(&evidence);
    assert!(!f.errors().is_empty());
    fs::write(f.0.join("evidence/test.rule.json"), [0xff]).unwrap();
    assert!(!f.errors().is_empty());
}
